def check_title_clip_pin() -> None:
    """Title continue hangs a tiny clip_card pin after upload; Week 1 / pre-upload hide it."""
    title_cs = (ROOT / "Assets/Scripts/Presentation/TitleDirector.cs").read_text(encoding="utf-8")
