def check_letter_keycaps() -> None:
    import struct

    settle_cs = (ROOT / "Assets/Scripts/Presentation/SettlementDirector.cs").read_text(encoding="utf-8")
    art_cs = (ROOT / "Assets/Scripts/Presentation/ArtSprites.cs").read_text(encoding="utf-8")
    title_cs = (ROOT / "Assets/Scripts/Presentation/TitleDirector.cs").read_text(encoding="utf-8")
    live_cs = (ROOT / "Assets/Scripts/Presentation/LiveStreamDirector.cs").read_text(encoding="utf-8")
    week_cs = (ROOT / "Assets/Scripts/Presentation/WeekStartDirector.cs").read_text(encoding="utf-8")
    fandom_rules = (ROOT / "Assets/Scripts/Economy/FandomRules.cs").read_text(encoding="utf-8")
    fandom_asset = (ROOT / "Assets/Resources/Balance/FandomBalance.asset").read_text(encoding="utf-8")
    balance = (ROOT / "Assets/Resources/Balance/Week1Balance.asset").read_text(encoding="utf-8")
    player = (ROOT / "ProjectSettings/ProjectSettings.asset").read_text(encoding="utf-8")
    readme = (ROOT / "README.md").read_text(encoding="utf-8")
    letter_build = settle_cs.split('LetterRoot"', 1)[-1].split('MemberRoot"', 1)[0]
    reply_click = letter_build.split('"Reply"', 1)[-1].split('"Later"', 1)[0]
    later_click = letter_build.split('"Later"', 1)[-1].split("SafePairLayout", 1)[0]
    on_letter = settle_cs.split("void OnLetter", 1)[-1].split("void OnLetterLater", 1)[0]
    later_fn = settle_cs.split("void OnLetterLater", 1)[-1].split("void MaybeShowLetter", 1)[0]

    for name, label in (("letter_reply.png", "답장하기"), ("letter_ignore.png", "나중에")):
        png = ROOT / "Assets/Resources/Art" / name
        data = png.read_bytes() if png.exists() else b""
        w = h = color = 0
        if len(data) >= 26 and data[:8] == b"\x89PNG\r\n\x1a\n":
            w, h = struct.unpack(">II", data[16:24])
            color = data[25]
        if not png.exists() or png.stat().st_size < 8000:
            fail(f"{label} keycap PNG is missing")
            return
        if w < 360 or h < 140 or w <= h:
            fail(f"{label} keycap PNG is not a readable landscape stream-deck key")
            return
        if color != 6:
            fail(f"{label} keycap PNG is not RGBA")
            return

    if 'LetterReply = "Art/letter_reply"' not in art_cs or 'LetterIgnore = "Art/letter_ignore"' not in art_cs:
        fail("ArtSprites does not hook letter_reply / letter_ignore")
    elif "ArtSprites.LetterReply" not in reply_click or "답장하기" not in letter_build:
        fail("답장하기 does not hang letter_reply keycap")
    elif "ArtSprites.LetterIgnore" not in later_click or "나중에" not in letter_build:
        fail("나중에 does not hang letter_ignore keycap")
    elif "ArtSprites.LetterCard" not in letter_build or 'LetterCard = "Art/letter_card"' not in art_cs:
        fail("letter keycaps dropped letter_card paper")
    elif "PlayLetterSfx();" not in on_letter or "Audio/sfx_letter" not in settle_cs:
        fail("letter keycaps dropped sfx_letter on reply")
    elif "PlayLetterSfx" in later_fn:
        fail("letter ignore keycap plays sfx_letter")
    elif "SendLetter" not in on_letter or "CloseLetter(true)" not in later_fn:
        fail("letter keycaps changed reply / ignore routing")
    elif "letterLoyalty: 4" not in fandom_asset or "letterMental: 8" not in fandom_asset:
        fail("letter keycaps retuned loyalty / mental")
    elif "CanSendLetter" not in fandom_rules or "ShouldOfferLetter" not in fandom_rules:
        fail("letter keycaps changed offer / send routing")
    elif "ArtSprites.GoLiveKey" not in week_cs or "ArtSprites.NextDayKey" not in settle_cs:
        fail("letter keycaps dropped morning/settlement keycap match")
    elif "billRent: 8000" not in balance or "startingCash: 45000" not in balance:
        fail("letter keycaps retuned Week 1 economy")
    elif "AddColumnPad" not in live_cs or "입력됨" not in live_cs or "timeScale" in live_cs:
        fail("letter keycaps broke pads, 입력됨, or added timeScale")
    elif "Week2" in title_cs or "Fandom" in title_cs or "민준" in title_cs or "토크" in title_cs:
        fail("Title started advertising letter keycaps / later weeks")
    elif "defaultScreenOrientation: 0" not in player:
        fail("letter keycaps dropped the Android Portrait lock")
    elif "6000.5.9f1" not in (ROOT / "ProjectSettings/ProjectVersion.txt").read_text(encoding="utf-8"):
        fail("letter keycaps moved Unity off 6000.5.9f1")
    elif "Art/letter_reply" not in readme or "Art/letter_ignore" not in readme:
        fail("README should mention letter_reply / letter_ignore")
    else:
        ok("letter 답장하기 / 나중에 sit on keycaps; paper / sfx / rewards stay")


def check_pad_sfx() -> None:
    import wave

    live_cs = (ROOT / "Assets/Scripts/Presentation/LiveStreamDirector.cs").read_text(encoding="utf-8")
    pad_cs = (ROOT / "Assets/Scripts/Input/StreamPadButton.cs").read_text(encoding="utf-8")
    bind_cs = (ROOT / "Assets/Scripts/Input/StreamBindings.cs").read_text(encoding="utf-8")
    title_cs = (ROOT / "Assets/Scripts/Presentation/TitleDirector.cs").read_text(encoding="utf-8")
    rules_cs = (ROOT / "Assets/Scripts/Stream/StreamRules.cs").read_text(encoding="utf-8")
    balance = (ROOT / "Assets/Resources/Balance/Week1Balance.asset").read_text(encoding="utf-8")
    player = (ROOT / "ProjectSettings/ProjectSettings.asset").read_text(encoding="utf-8")
    judge = live_cs.split("if (_session.LastJudgement.HasValue", 1)[-1].split("SyncNotes();", 1)[0]
    press = pad_cs.split("public void Press()", 1)[-1].split("public void Release()", 1)[0]
    update = live_cs.split("void Update()", 1)[-1].split("void LateUpdate", 1)[0]
    if "void LateUpdate" not in live_cs:
        update = live_cs.split("void Update()", 1)[-1].split("void Echo(", 1)[0]
    path = ROOT / "Assets/Resources/Audio/sfx_pad.wav"
    if not path.exists() or path.stat().st_size < 1500:
        fail("sfx_pad.wav is missing")
        return
    with wave.open(str(path), "rb") as w:
        if w.getnchannels() < 1 or w.getsampwidth() != 2 or w.getframerate() < 22050:
            fail("sfx_pad.wav is not a readable PCM click")
            return
        dur = w.getnframes() / float(w.getframerate())
        if dur < 0.03 or dur > 0.12:
            fail(f"sfx_pad.wav duration {dur:.3f}s is not a short keycap click")
            return

    if "Audio/sfx_pad" not in live_cs or "PlayPadClick" not in live_cs:
        fail("LiveStream does not load / play Audio/sfx_pad")
    elif "OnLanePadPress" not in bind_cs or "LaneKeyboardPressDown" not in bind_cs:
        fail("pad click hooks are missing from StreamBindings")
    elif "OnLanePadPress" not in press or "QueueKind" not in press or "BeginSuperchatCharge" not in press:
        fail("kind / superchat pad-down does not fire the click")
    elif "OnLanePadPress" in press.split("case Mode.Event", 1)[-1].split("case Mode.PromoConfirm", 1)[0]:
        fail("event pads play the lane keycap click")
    elif "LaneKeyboardPressDown" not in update or "PlayPadClick" not in update:
        fail("keyboard kind / superchat pad-down does not play the click")
    elif "PlaySfx(_padClick" in judge or "PlayPadClick" in judge:
        fail("pad click plays on judge instead of press")
    elif "PlaySfx(_perfect" not in judge or "PlaySfx(_good" not in judge or "PlaySfx(_miss" not in judge:
        fail("pad click dropped Perfect / Good / Miss SFX")
    elif "PlaySfx(_sc" not in judge:
        fail("pad click moved superchat chime off hit")
    elif "_flash = 0.08f" not in pad_cs or "pad?.Flash()" not in live_cs:
        fail("pad click changed the 0.08s flash")
    elif "TryConsumeKind" not in bind_cs or "GetKeyDown(KeyCode.LeftArrow)" not in bind_cs:
        fail("pad click retuned keyboard bindings")
    elif "슈퍼챗" not in live_cs or "SetPulse" not in live_cs:
        fail("pad click dropped superchat pip / telegraph pulse")
    elif "perfectWindow: 0.07" not in balance or "goodWindow: 0.22" not in balance:
        fail("pad click retuned hit windows")
    elif "perfectWindow * " not in rules_cs or "b.goodWindow" not in rules_cs:
        fail("pad click retuned Judge windows")
    elif "billRent: 8000" not in balance or "startingCash: 45000" not in balance:
        fail("pad click retuned Week 1 economy")
    elif "AddColumnPad" not in live_cs or "입력됨" not in live_cs or "timeScale" in live_cs:
        fail("pad click broke pads, 입력됨, or added timeScale")
    elif "Week2" in title_cs or "Fandom" in title_cs or "민준" in title_cs or "토크" in title_cs:
        fail("Title started advertising pad click / later weeks")
    elif "defaultScreenOrientation: 0" not in player:
        fail("pad click dropped the Android Portrait lock")
    elif "6000.5.9f1" not in (ROOT / "ProjectSettings/ProjectVersion.txt").read_text(encoding="utf-8"):
        fail("pad click moved Unity off 6000.5.9f1")
    else:
        ok("kind / superchat pads play sfx_pad once on press; judge / chime stay")


